// WP-6.4 in-tree denoiser (SVGF / A-SVGF on render graph v2): see
// include/fuse/renderer/denoise/svgf_denoiser.hpp.
#include <fuse/renderer/denoise/svgf_denoiser.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>
#include <initializer_list>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp64.cmake from shaders/denoise/*: kDn<Kernel><Slang|Glsl>Spv and
// FUSE_DENOISE_{SLANG,GLSL} when every kernel of a language exists.
#include "denoise_spv.h"
#endif

namespace fuse::renderer::denoise {

namespace {
constexpr u32 kPushBytes = sizeof(DenoisePush);
constexpr u32 kFrameStride = 256u; ///< ring slot size (>= sizeof(DenoiseFrameConstants), 256-aligned)
static_assert(sizeof(DenoiseFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kOutputFormat = static_cast<u32>(GpuFormat::R16G16B16A16Sfloat);
constexpr u64 kTexel = 16u; ///< f32x4
constexpr u64 kPair = 8u;   ///< f32x2

BufferUsage bufferUsage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

ImageUsage imageUsage(std::initializer_list<ImageUsage> bits) {
    u32 u = 0;
    for (const ImageUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<ImageUsage>(u);
}

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 groups(u32 items) { return items == 0u ? 1u : (items + kDenoiseTile - 1u) / kDenoiseTile; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

SvgfBufferLayout SvgfBufferLayout::compute(u32 width, u32 height, bool keepIntermediates) {
    SvgfBufferLayout l{};
    l.width = width;
    l.height = height;
    l.strataW = strata(width);
    l.strataH = strata(height);
    l.keepIntermediates = keepIntermediates;
    const u64 n = static_cast<u64>(width) * height;
    const u64 ns = static_cast<u64>(l.strataW) * l.strataH;
    u64 cursor = 0;
    auto take = [&cursor](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 16u));
        return at;
    };
    for (u32 k = 0; k < 2u; ++k) {
        l.guide[k] = take(n * kTexel);
    }
    for (u32 k = 0; k < 2u; ++k) {
        l.hist[k] = take(n * kTexel);
    }
    for (u32 k = 0; k < 2u; ++k) {
        l.mom[k] = take(n * kTexel);
    }
    l.stateBytes = cursor;
    cursor = 0;
    l.gradZ = take(n * kPair);
    l.accum = take(n * kTexel);
    if (keepIntermediates) {
        l.variance = take(n * kTexel);
        for (u64& a : l.atrous) {
            a = take(n * kTexel);
        }
        for (u64& g : l.gradient) {
            g = take(ns * kTexel);
        }
    } else {
        const u64 ping[2] = {take(n * kTexel), take(n * kTexel)};
        l.variance = ping[0];
        for (u32 k = 0; k < kDenoiseMaxAtrous; ++k) {
            l.atrous[k] = ping[(k + 1u) & 1u];
        }
        const u64 g[2] = {take(ns * kTexel), take(ns * kTexel)};
        for (u32 k = 0; k <= kDenoiseMaxGradientIterations; ++k) {
            l.gradient[k] = g[k & 1u];
        }
    }
    l.workBytes = cursor;
    l.outputBytes = std::max<u64>(n * kTexel, 16u);
    return l;
}

DenoiseCapabilities queryDenoiseCapabilities(const VulkanDevice* device) {
    DenoiseCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    VkFormatProperties props{};
    vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()),
                                        static_cast<VkFormat>(kOutputFormat), &props);
    if ((props.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u) {
        c.reason = "RGBA16F storage images unsupported";
        return c;
    }
    c.denoise = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

SvgfDenoiser::~SvgfDenoiser() { destroy(); }

bool SvgfDenoiser::init(const SvgfDenoiserDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u) {
        return false;
    }
    if (!queryDenoiseCapabilities(desc.device).denoise) {
        return false;
    }
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "svgf_denoiser.frame";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr ||
        m_frameRing.deviceAddress == 0u || !createPipelines()) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void SvgfDenoiser::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    Retired current{};
    current.buffers[0] = m_state;
    current.buffers[1] = m_work;
    current.buffers[2] = m_output;
    current.image = m_image.image;
    current.slots[0] = m_image.slot;
    current.slots[1] = m_normalSlot;
    destroyRetired(current);
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_state = m_work = m_output = Buffer{};
    m_stateQueue = m_workQueue = m_outputQueue = rg::kNoQueue;
    m_image = Image{};
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_retired.clear();
    m_normalImage = nullptr;
    m_normalSlot = BindlessSlotHandle{};
    m_normalHandle = 0;
    m_layout = SvgfBufferLayout{};
    m_historyValid = false;
    m_parity = 1u;
    m_recordCount = 0;
    m_language = "none";
    m_stats = DenoiseStats{};
    m_initialized = false;
}

bool SvgfDenoiser::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_DENOISE_SLANG)
    if (m_desc.language == DenoiseKernelLanguage::Auto || m_desc.language == DenoiseKernelLanguage::Slang) {
        k[kGuide] = code(kDnGuideSlangSpv);
        k[kGradient] = code(kDnGradientSlangSpv);
        k[kTemporal] = code(kDnTemporalSlangSpv);
        k[kVariance] = code(kDnVarianceSlangSpv);
        k[kAtrous] = code(kDnAtrousSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_DENOISE_GLSL)
    if (!found && (m_desc.language == DenoiseKernelLanguage::Auto || m_desc.language == DenoiseKernelLanguage::Glsl)) {
        k[kGuide] = code(kDnGuideGlslSpv);
        k[kGradient] = code(kDnGradientGlslSpv);
        k[kTemporal] = code(kDnTemporalGlslSpv);
        k[kVariance] = code(kDnVarianceGlslSpv);
        k[kAtrous] = code(kDnAtrousGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool SvgfDenoiser::createResources(u32 width, u32 height) {
    const SvgfBufferLayout layout = SvgfBufferLayout::compute(width, height, m_desc.keepIntermediates);
    const BufferUsage usage = bufferUsage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    Buffer fresh[3]{};
    const u64 sizes[3] = {layout.stateBytes, layout.workBytes, layout.outputBytes};
    const char* names[3] = {"svgf_denoiser.state", "svgf_denoiser.work", "svgf_denoiser.output"};
    bool ok = true;
    for (u32 i = 0; i < 3u && ok; ++i) {
        BufferDesc d{};
        d.size = static_cast<usize>(sizes[i]);
        d.usage = usage;
        d.memoryUsage = MemoryUsage::GpuOnly;
        d.name = names[i];
        ok = m_desc.allocator->createBuffer(d, fresh[i]) && fresh[i].deviceAddress != 0u;
    }
    Image image{};
    if (ok) {
        TextureDesc d{};
        d.width = width;
        d.height = height;
        d.format = static_cast<GpuFormat>(kOutputFormat);
        d.usage = imageUsage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc});
        d.name = "svgf_denoiser.output_image";
        ok = m_desc.allocator->createImage(d, image.image);
        if (ok) {
            image.slot = m_desc.bindless->registerTextureSlot(image.image, true);
            ok = image.slot.isValid();
        }
    }
    if (!ok) {
        Retired failed{};
        for (u32 i = 0; i < 3u; ++i) {
            failed.buffers[i] = fresh[i];
        }
        failed.image = image.image;
        failed.slots[0] = image.slot;
        destroyRetired(failed);
        return false;
    }
    if (m_state.handle != nullptr || m_image.image.image != nullptr) {
        Retired old{};
        old.buffers[0] = m_state;
        old.buffers[1] = m_work;
        old.buffers[2] = m_output;
        old.image = m_image.image;
        old.slots[0] = m_image.slot;
        retire(old);
    }
    m_state = fresh[0];
    m_work = fresh[1];
    m_output = fresh[2];
    m_stateQueue = m_workQueue = m_outputQueue = rg::kNoQueue;
    m_image = image;
    m_layout = layout;
    m_historyValid = false;
    ++m_stats.stateRebuilds;
    return true;
}

bool SvgfDenoiser::bindNormalImage(const Texture* image) {
    void* handle = image != nullptr ? image->image : nullptr;
    if (handle == m_normalImage && (handle == nullptr || m_normalSlot.isValid())) {
        return true;
    }
    if (m_normalSlot.isValid()) {
        Retired old{};
        old.slots[1] = m_normalSlot;
        retire(old);
    }
    m_normalSlot = BindlessSlotHandle{};
    m_normalImage = nullptr;
    m_normalHandle = 0u;
    if (handle == nullptr) {
        return true;
    }
    m_normalSlot = m_desc.bindless->registerTextureSlot(*image, false);
    if (!m_normalSlot.isValid()) {
        return false;
    }
    m_normalImage = handle;
    m_normalHandle = m_desc.bindless->shaderHandle(m_normalSlot);
    ++m_stats.inputBinds;
    return true;
}

void SvgfDenoiser::retire(Retired r) {
    r.serial = m_frameSerial;
    m_retired.push_back(r);
    ++m_stats.retired;
}

void SvgfDenoiser::destroyRetired(Retired& r) {
    for (BindlessSlotHandle& slot : r.slots) {
        if (slot.isValid()) {
            m_desc.bindless->unregisterSlot(slot);
        }
    }
    for (Buffer& b : r.buffers) {
        if (b.handle != nullptr) {
            m_desc.allocator->destroyBuffer(b);
        }
    }
    if (r.image.image != nullptr) {
        m_desc.allocator->destroyImage(r.image);
    }
    r = Retired{};
}

u32 SvgfDenoiser::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyRetired(m_retired[i]);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

void SvgfDenoiser::setSettings(const SvgfSettings& settings) {
    m_settings = settings;
    if (settings.signal != m_lastSignal) {
        m_historyValid = false;
        m_lastSignal = settings.signal;
    }
}

u32 SvgfDenoiser::outputImageHandle() const {
    return m_image.slot.isValid() ? m_desc.bindless->shaderHandle(m_image.slot) : 0u;
}

bool SvgfDenoiser::beginFrame(u64 frameSerial, const DenoiseFrameDesc& frame) {
    if (!m_initialized || frame.width == 0u || frame.height == 0u || frame.signal == 0u || frame.motion == 0u ||
        frame.depth == 0u || (frame.normal == 0u && frame.normalImage == nullptr) ||
        (m_settings.gradients && frame.gradient == 0u)) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    if (frame.width != m_layout.width || frame.height != m_layout.height || m_state.handle == nullptr) {
        if (!createResources(frame.width, frame.height)) {
            return false;
        }
    }
    if (!bindNormalImage(frame.normalImage)) {
        return false;
    }
    m_normalFromImage = m_normalHandle != 0u;
    if (frame.reset) {
        m_historyValid = false;
    }
    m_parity ^= 1u;
    const u32 cur = m_parity;
    const u32 prev = cur ^ 1u;
    DenoiseFrameConstants c = resolve_constants(m_settings, frame.width, frame.height, m_historyValid, m_normalFromImage);
    if (m_normalFromImage) {
        c.flags |= kDenoiseFlagNormalImage;
        c.normalImage = m_normalHandle;
    } else {
        c.normal = frame.normal;
    }
    const u64 state = m_state.deviceAddress;
    const u64 work = m_work.deviceAddress;
    c.signal = frame.signal;
    c.motion = frame.motion;
    c.depth = frame.depth;
    c.gradientIn = m_settings.gradients ? frame.gradient : 0u;
    c.guideCur = state + m_layout.guide[cur];
    c.guidePrev = state + m_layout.guide[prev];
    c.histCur = state + m_layout.hist[cur];
    c.histPrev = state + m_layout.hist[prev];
    c.momCur = state + m_layout.mom[cur];
    c.momPrev = state + m_layout.mom[prev];
    c.gradZ = work + m_layout.gradZ;
    c.accum = work + m_layout.accum;
    c.lambda = work + m_layout.gradient[c.gradientIterations];
    c.output = m_output.deviceAddress;
    c.outputImage = m_desc.bindless->shaderHandle(m_image.slot);
    m_constants = c;
    m_stats.history = m_historyValid;
    m_stats.gradients = m_settings.gradients;
    const u32 slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    const u64 offset = static_cast<u64>(slot) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &c, sizeof(c));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    m_historyValid = true; // the next frame reprojects this one
    return true;
}

DenoiseGraphRefs SvgfDenoiser::importInto(rg::Graph& graph) {
    DenoiseGraphRefs refs{};
    if (!m_initialized || m_state.handle == nullptr) {
        return refs;
    }
    refs.state = graph.importBuffer(
        rg::ImportedBuffer{m_state.handle, m_state.desc.size, m_stateQueue, &m_stateQueue, "svgf_denoiser.state"});
    refs.work = graph.importBuffer(
        rg::ImportedBuffer{m_work.handle, m_work.desc.size, m_workQueue, &m_workQueue, "svgf_denoiser.work"});
    refs.output = graph.importBuffer(
        rg::ImportedBuffer{m_output.handle, m_output.desc.size, m_outputQueue, &m_outputQueue, "svgf_denoiser.output"});
    rg::ImportedImage i{};
    i.image = m_image.image.image;
    i.view = m_image.image.view;
    i.format = kOutputFormat;
    i.width = m_layout.width;
    i.height = m_layout.height;
    i.initialLayout = m_image.layout;
    i.initialQueue = m_image.queue;
    i.layoutTracker = &m_image.layout;
    i.queueTracker = &m_image.queue;
    i.name = "svgf_denoiser.output_image";
    refs.outputImage = graph.importImage(i);
    return refs;
}

SvgfDenoiser::PassRecord* SvgfDenoiser::nextRecord(u32 kernel) {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->kernel = kernel;
    r->push.frame = m_frameAddress;
    return r;
}

void SvgfDenoiser::addPasses(rg::Graph& graph, const DenoiseGraphRefs& refs, const DenoiseGraphInputs& inputs) {
    const DenoiseFrameConstants& c = m_constants;
    if (!m_initialized || !refs.state.valid() || !refs.work.valid() || !refs.output.valid() || !refs.outputImage.valid() ||
        !inputs.signal.valid() || !inputs.motion.valid() || !inputs.depth.valid() ||
        (m_normalFromImage ? !inputs.normalImage.valid() : !inputs.normal.valid()) ||
        (m_settings.gradients && !inputs.gradient.valid())) {
        return;
    }
    const u32 w = m_layout.width;
    const u32 h = m_layout.height;
    const u64 work = m_work.deviceAddress;
    constexpr u8 kCs = rg::kStageCompute;
    auto pixels = [&](PassRecord* r) {
        r->groups[0] = groups(w);
        r->groups[1] = groups(h);
    };
    auto add = [&](const char* name, PassRecord* r) {
        ++m_stats.passes;
        rg::PassBuilder pass = graph.addPass(name, &SvgfDenoiser::recordDispatch, r);
        pass.use(refs.state, rg::Access::StorageReadWrite, {}, kCs).use(refs.work, rg::Access::StorageReadWrite, {}, kCs);
        return pass;
    };

    // denoise.guide
    if (PassRecord* r = nextRecord(kGuide)) {
        pixels(r);
        rg::PassBuilder pass = add("denoise.guide", r);
        pass.use(inputs.depth, rg::Access::StorageRead, {}, kCs);
        if (m_normalFromImage) {
            pass.use(inputs.normalImage, rg::Access::SampledRead, {}, kCs);
        } else {
            pass.use(inputs.normal, rg::Access::StorageRead, {}, kCs);
        }
    }

    // A-SVGF gradients
    if (m_settings.gradients) {
        if (PassRecord* r = nextRecord(kGradient)) {
            r->push.mode = kDenoiseGradientPrepare;
            r->push.src = c.gradientIn;
            r->push.dst = work + m_layout.gradient[0];
            r->groups[0] = groups(c.strataW);
            r->groups[1] = groups(c.strataH);
            add("denoise.gradient.prepare", r).use(inputs.gradient, rg::Access::StorageRead, {}, kCs);
        }
        for (u32 k = 0; k < c.gradientIterations; ++k) {
            if (PassRecord* r = nextRecord(kGradient)) {
                r->push.mode = kDenoiseGradientAtrous;
                r->push.src = work + m_layout.gradient[k];
                r->push.dst = work + m_layout.gradient[k + 1u];
                r->push.step = 1u << k;
                r->groups[0] = groups(c.strataW);
                r->groups[1] = groups(c.strataH);
                add("denoise.gradient.atrous", r);
            }
        }
    }

    // denoise.temporal
    if (PassRecord* r = nextRecord(kTemporal)) {
        pixels(r);
        add("denoise.temporal", r)
            .use(inputs.signal, rg::Access::StorageRead, {}, kCs)
            .use(inputs.motion, rg::Access::StorageRead, {}, kCs);
    }

    // denoise.variance
    if (PassRecord* r = nextRecord(kVariance)) {
        pixels(r);
        r->push.dst = work + m_layout.variance;
        add("denoise.variance", r);
    }

    // denoise.atrous x N
    for (u32 k = 0; k < c.atrousIterations; ++k) {
        PassRecord* r = nextRecord(kAtrous);
        if (r == nullptr) {
            break;
        }
        const bool last = k + 1u == c.atrousIterations;
        pixels(r);
        r->push.src = work + (k == 0u ? m_layout.variance : m_layout.atrous[k - 1u]);
        r->push.dst = last ? c.output : work + m_layout.atrous[k];
        r->push.aux = k == c.historyTap ? c.histCur : 0u;
        r->push.step = 1u << k;
        r->push.flags = last ? kDenoisePassWriteImage : 0u;
        rg::PassBuilder pass = add("denoise.atrous", r);
        if (last) {
            pass.use(refs.output, rg::Access::StorageWrite, {}, kCs).use(refs.outputImage, rg::Access::StorageWrite, {}, kCs);
        }
    }
}

void SvgfDenoiser::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const SvgfDenoiser& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes,
                       &r.push);
    vkCmdDispatch(cmd, r.groups[0], r.groups[1], 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::denoise
